/**
 * Overridden to fix spacing issues on the vertical and horizontal axes.
 */
public class JgtTidierTreeLayoutAlgorithm : TidierTreeLayoutAlgorithm<AttributedVertex, AttributedEdge> {

	/* @SuppressWarnings("unchecked") */
	public static Builder<object,object> edgeAwareBuilder() {
		return new();
	}

	public JgtTidierTreeLayoutAlgorithm(Builder<object,object> builder) : base(builder)
    {

		// when true, excess vertical space sometimes appears that users don't like
		expandLayout = false;
	}

	/* @Override */
	protected Dimension computeAverageVertexDimension<E>(Graph<AttributedVertex, E> graph,
			Function<AttributedVertex, Rectangle> shapeFunction) {

		// The super call uses the average size of the vertices to create spacing.  Large vertices
		// can cause a large amount of space to be used on the x axis. 
		return Dimension.of(50, 50);
	}

	//@formatter:off
	public static class Builder<T, B> : TidierTreeLayoutAlgorithm.Builder<AttributedVertex, AttributedEdge, T, B> where T : TidierTreeLayoutAlgorithm<AttributedVertex, AttributedEdge> where B : Builder<T, B> {

		/* @SuppressWarnings("unchecked") */
		/* @Override */
		public T build() {
			return (T) new JgtTidierTreeLayoutAlgorithm(this);
		}
	}
	//@formatter:on
}
